// ChoosePixelFormat calls GDI32!ChoosePixelFormat.
// https://learn.microsoft.com/windows/win32/api/wingdi/nf-wingdi-choosepixelformat
// Minimum OS: windows5.0.
func ChoosePixelFormat(hdc graphicsgdi.HDC, ppfd *PIXELFORMATDESCRIPTOR) (int32, error) {
	r1, _, e1 := syscall.SyscallN(procChoosePixelFormat.Addr(), uintptr(hdc), uintptr(unsafe.Pointer(ppfd)))
	if e1 != 0 {
		return int32(r1), e1
	}
	return int32(r1), nil
}

